#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: login real en producción (tarea 9). Configura Supabase Auth, los
# proveedores OAuth y la CI de migraciones, e invita al owner.
# Uso (raíz del repo): & "C:\Program Files\Git\bin\bash.exe" scripts/wizard-login.sh
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8
GH_ENV="production"
REPO=$(gh repo view --json nameWithOwner --jq .nameWithOwner 2>/dev/null || true)
REF=$(gh variable get SUPABASE_PROJECT_REF --env "$GH_ENV" 2>/dev/null || true)
APP_URL=$(gh variable get PRODUCTION_URL --env "$GH_ENV" 2>/dev/null || true)
supabase() { pnpm exec supabase "$@"; }

# Los secretos van directo a GitHub o a Supabase: nada se guarda en disco.
ENV_FILE="/dev/null"

# En Git Bash, explorer.exe convierte `=/…` en rutas: se abre el navegador con
# el manejador de URLs de Windows.
if command -v rundll32.exe >/dev/null 2>&1; then
  open_url() {
    printf '  %s↗ abriendo%s %s\n' "$GREEN" "$RESET" "$1"
    MSYS_NO_PATHCONV=1 rundll32.exe url.dll,FileProtocolHandler "$1" >/dev/null 2>&1 ||
      warn "no pude abrir el navegador; abrí la URL a mano: $1"
  }
fi

set_env_secret() {
  if printf '%s' "$2" | gh secret set "$1" --env "$GH_ENV" --repo "$REPO" >/dev/null 2>&1; then
    WRITTEN_SECRET+=("$1")
    printf '  %s✓ set%s secreto %s (entorno %s)\n' "$GREEN" "$RESET" "$1" "$GH_ENV"
  else
    SKIPPED+=("secreto $1: gh secret set $1 --env $GH_ENV --repo $REPO")
    warn "no pude guardar el secreto $1"
  fi
}

set_env_var() {
  if gh variable set "$1" --env "$GH_ENV" --repo "$REPO" --body "$2" >/dev/null 2>&1; then
    printf '  %s✓ set%s variable %s (entorno %s)\n' "$GREEN" "$RESET" "$1" "$GH_ENV"
  else
    SKIPPED+=("variable $1: gh variable set $1 --env $GH_ENV --repo $REPO --body <valor>")
    warn "no pude guardar la variable $1"
  fi
}

if [[ -z "$REPO" || -z "$REF" || -z "$APP_URL" ]]; then
  printf '%sFalta configuración: corré primero scripts/wizard-deploy.sh (y gh auth login).%s\n' "$RED" "$RESET"
  exit 1
fi
CALLBACK="https://${REF}.supabase.co/auth/v1/callback"
HOOK_URI="pg-functions://postgres/private/before_user_created"

banner "Plektia · login con GitHub y Google en producción"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Supabase: iniciar sesión en la CLI"
note "Para pegar en esta terminal: clic derecho o Shift+Insert. Ctrl+C corta el wizard."
say "La CLI necesita tu sesión para aplicar migraciones e invitar usuarios."
if supabase projects list >/dev/null 2>&1; then
  printf '  %s✓ ya tenés sesión en la CLI de Supabase%s\n' "$GREEN" "$RESET"
else
  step "Se abre el navegador: autorizá el acceso y volvé acá."
  pause "Enter para abrir el login..."
  supabase login
fi
pause "Enter para seguir"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Supabase: token y contraseña para la CI"
say "La CI aplica las migraciones con un token de acceso y la contraseña de la base."
warn "El token de Supabase alcanza a toda tu cuenta: queda solo en el entorno 'production'."
open_url "https://supabase.com/dashboard/account/tokens"
step "Tocá 'Generate new token'. Nombre: plektia-ci. Si te ofrece vencimiento, elegí 1 año."
note "Al pegar no se ve nada (es a propósito): clic derecho o Shift+Insert y Enter."
ask_secret SUPABASE_ACCESS_TOKEN "Pegá el token:"
step "Ahora la contraseña de la base que guardaste al crear el proyecto (gestor de contraseñas)."
ask_secret SUPABASE_DB_PASSWORD "Pegá la contraseña de la base:"
export SUPABASE_ACCESS_TOKEN SUPABASE_DB_PASSWORD
say "Verificando contra el proyecto (sin cambiar nada)..."
if supabase db push --project-ref "$REF" --dry-run; then
  printf '  %s✓ token y contraseña válidos%s\n' "$GREEN" "$RESET"
  set_env_secret SUPABASE_ACCESS_TOKEN "$SUPABASE_ACCESS_TOKEN"
  set_env_secret SUPABASE_DB_PASSWORD "$SUPABASE_DB_PASSWORD"
else
  warn "Supabase rechazó el token o la contraseña: revisalos y volvé a correr el wizard."
  exit 1
fi
pause "Enter para seguir"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Supabase: aplicar las migraciones"
say "Crea en producción el esquema de identidad: allowlist, perfiles, hook y RLS."
note "Desde ahora la CI las aplica sola en cada deploy."
if confirm "¿Aplico las migraciones en producción?"; then
  supabase db push --project-ref "$REF"
else
  SKIPPED+=("migraciones: se aplican en el próximo deploy")
fi
pause "Enter para seguir"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Supabase: clave pública del proyecto"
say "La publishable key es pública por diseño (va al navegador). La tomo de la CLI."
PUBLISHABLE_KEY=$(supabase projects api-keys --project-ref "$REF" -o json 2>/dev/null | node scripts/wizard-helpers.mjs publishable-key || true)
if [[ -n "$PUBLISHABLE_KEY" ]]; then
  printf '  %s✓ publishable key obtenida%s\n' "$GREEN" "$RESET"
else
  open_url "https://supabase.com/dashboard/project/${REF}/settings/api-keys"
  step "Copiá la 'Publishable key' (empieza con sb_publishable_)."
  ask PUBLISHABLE_KEY "Pegá la publishable key:"
fi
set_env_var SUPABASE_PUBLISHABLE_KEY "$PUBLISHABLE_KEY"
pause "Enter para seguir"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "GitHub: OAuth App"
open_url "https://github.com/settings/applications/new"
step "Application name: Plektia"
step "Homepage URL: ${APP_URL}"
step "Authorization callback URL: ${CALLBACK}"
step "Dejá 'Enable Device Flow' sin marcar y tocá 'Register application'."
ask GITHUB_CLIENT_ID "Pegá el Client ID:"
step "Tocá 'Generate a new client secret' y copialo (se muestra una sola vez)."
ask_secret GITHUB_SECRET "Pegá el client secret:"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Google: cliente OAuth"
open_url "https://console.cloud.google.com/auth/overview"
step "Si te lo pide, creá un proyecto: plektia."
step "Branding (o Get started): nombre Plektia, tu email de soporte, público External."
step "Clients → Create client → Web application. Nombre: Plektia."
step "Authorized redirect URIs → Add URI: ${CALLBACK}"
step "Create → copiá el Client ID y el Client secret."
note "Si la consola no coincide con estos pasos, mandale una captura a Claude."
ask GOOGLE_CLIENT_ID "Pegá el Client ID:"
ask_secret GOOGLE_SECRET "Pegá el client secret:"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Supabase: configurar Auth"
say "Aplico por la API de gestión de Supabase:"
step "URL del sitio ${APP_URL} y callback permitido ${APP_URL}/auth/callback"
step "GitHub y Google activados; email y teléfono desactivados"
step "Hook before_user_created: solo entran los invitados"
if confirm "¿Aplico la configuración?"; then
  export APP_URL GITHUB_CLIENT_ID GITHUB_SECRET GOOGLE_CLIENT_ID GOOGLE_SECRET HOOK_URI
  if node scripts/wizard-helpers.mjs auth-config |
    curl -fsS -X PATCH "https://api.supabase.com/v1/projects/${REF}/config/auth" \
      -H "Authorization: Bearer ${SUPABASE_ACCESS_TOKEN}" -H "Content-Type: application/json" \
      --data @- -o /dev/null; then
    printf '  %s✓ configuración enviada%s\n' "$GREEN" "$RESET"
  fi
  unset GITHUB_SECRET GOOGLE_SECRET
  say "Verificando lo que quedó en Supabase..."
  if ! curl -fsS "https://api.supabase.com/v1/projects/${REF}/config/auth" \
    -H "Authorization: Bearer ${SUPABASE_ACCESS_TOKEN}" | node scripts/wizard-helpers.mjs verify-auth; then
    warn "Algo no quedó como se esperaba: revisalo en Authentication del panel de Supabase."
    open_url "https://supabase.com/dashboard/project/${REF}/auth/providers"
    SKIPPED+=("revisar Auth en el panel de Supabase (proveedores y hook)")
  fi
else
  SKIPPED+=("configuración de Auth en Supabase")
fi
pause "Enter para seguir"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Invitarte como owner"
say "Tu email tiene que ser el mismo (y verificado) que usás en GitHub y en Google."
ask OWNER_EMAIL "Tu email:"
if confirm "¿Invito a ${OWNER_EMAIL} como owner con el handle juedsay?"; then
  supabase link --project-ref "$REF" >/dev/null
  pnpm user:allow "$OWNER_EMAIL" juedsay --role owner --prod
fi
unset SUPABASE_ACCESS_TOKEN SUPABASE_DB_PASSWORD

finish
say "Con el próximo deploy, probá: ${APP_URL}/login"
